#define TAU 6.2831853

// Custom vibrant color palette function
vec3 palette(float t) {
    return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy, uv = u / R;
    float Rxy = length(R);

    O *= 0.0;

    float[] gk1s = float[](
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.023792, 0.094907, 0.150342, 0.094907, 0.023792,
        0.015019, 0.059912, 0.094907, 0.059912, 0.015019,
        0.003765, 0.015019, 0.023792, 0.015019, 0.003765
    );

    vec4 total_color = vec4(0.0, 0.0, 0.0, 0.0);
    vec2 tex = 1.0 / R.xy;
    float one_pixel = 4.0 / Rxy;
    float pix = one_pixel / sqrt(2.0);
    float green = 0.0;

    // Audio reactivity: sample from iChannel0
    float audio = texture(iChannel1, vec2(0.01, uv.y)).r;

    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            vec4 x2 = texture(iChannel1, uv + vec2(0.0, one_pixel) + vec2(i - 2, j - 2) * tex);
            vec4 x3 = texture(iChannel1, uv + vec2(pix, pix) + vec2(i - 2, j - 2) * tex);
            vec4 x4 = texture(iChannel1, uv + vec2(0.0, -one_pixel) + vec2(i - 2, j - 2) * tex);

            float a = x3.x * x2.y - x3.y * x2.x;
            float c = x3.x * x2.w - x3.w * x2.x;
            float e = x3.y * x2.w - x3.w * x2.y;

            green += gk1s[i * 5 + j] * (a * x4.w - c * x4.y + e * x4.x);
        }
    }

    float intensity = 0.4 - green * Rxy * Rxy / 2000.0;
    vec4 actual_pixel = texture(iChannel0, uv);

    float colorMod = intensity;
    float glow = 0.8 * sin((1.0 + 0.5 * sin(iTime / 8.0)) * 10.0 * actual_pixel.z);

    // Apply palette and audio reactivity
    vec3 cc = colorMod * palette(0.5 + audio * 2.0) + glow * glow * palette(0.2 + audio);
    O = vec4(cc, 0.0);

    // Enhance glow
    O *= O;
    O *= O;
    O *= O;
    O = 1.0 - exp(-O);
}

