#define t iTime/2.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = (2.0*fragCoord-iResolution.xy)/iResolution.y;    

    vec2 center = vec2(-500,0);
    vec2 width  = vec2(20);

    vec2 z = uv * width + center ; 

    float max_iter=57.+0.*mod(iTime,30.), mix_factor=.986, infinity=1e3;

    vec2 wgt=vec2(mix_factor, 1.-mix_factor);

    float r=-.00164,an=1.95;  //the Julia set params, play with it
    vec2 jc = vec2(r*cos(an),r*sin(an)) ;

    float escape_value = 0., distance=0., too_small=1e-7;

    float invert = 1./max(z.x*z.x+z.y*z.y,too_small);    
    z *= invert;


    for ( float i=0.; i<max_iter; i++ ) {

        vec2 tmp = vec2(z.x*z.x*z.x - 3.*z.x*z.y*z.y,
                    -z.y*z.y*z.y + 3.*z.x*z.x*z.y);

        float div = max(tmp.x*tmp.x+tmp.y*tmp.y,too_small);

        //combo of abs(z^3) and abs(1/z^3)
        z = wgt.x*abs(tmp) + wgt.y*abs(tmp)/div+jc;

        distance = z.x*z.x + z.y*z.y;

        if ( distance > infinity ) {
            escape_value = i;
            break;
        }

    }

    if ( escape_value != 0. ) { 
        fragColor = vec4(0);
    }
    else {
        fragColor = vec4(uv,log(distance)/2.,log(distance)/2.);
    }


}
